"""Generate the six-manager report from frozen, completed experiments; never selects on holdout."""
from pathlib import Path
import json,math,statistics,csv,re,subprocess,gzip
D=Path('docs/research-180');R=Path('results/placement-study')
def load(name):
 p=R/(name+'.json');return json.loads(p.read_text() if p.exists() else gzip.decompress(Path(str(p)+'.gz').read_bytes()))
def f(x):return 'Unresolved' if x is None or not math.isfinite(x) else f'{x:.1f}'
def table(h,rows):return '| '+' | '.join(h)+' |\n|'+ '|'.join('---' for _ in h)+'|\n'+''.join('| '+' | '.join(str(v) for v in row)+' |\n' for row in rows)
def paired(a,b):
 q={r['seed']:r for r in b['runs']};ds=[r['tEvac']-q[r['seed']]['tEvac'] for r in a['runs'] if r['tEvac'] is not None and q[r['seed']]['tEvac'] is not None]
 if len(ds)!=len(a['runs']):return 'Unresolved'
 n=len(ds);z=1.959964;t=z+(z**3+z)/(4*(n-1))+(5*z**5+16*z**3+3*z)/(96*(n-1)**2);m=statistics.mean(ds);h=t*statistics.stdev(ds)/math.sqrt(n)
 return f'{m:.2f} [{m-h:.2f}, {m+h:.2f}]'

conf=load('confirmation');rows=conf['results'];sel=load('selection');short=load('shortlist');screen=load('screen');blocked=load('blocked');vis=load('visibility')
assert [len(d['results']) for d in [screen,short,conf,blocked,vis]] == [84,17,12,12,3], 'Incomplete experiment files'
get=lambda id,model:next(r for r in rows if r['id']==id and r['model']==model)
combined=get('combined-six','Lite');best=get('best-six','Lite');cfg=combined['cfg'];a=get('combined-six','A');b=get('combined-six','B');base=get('matched-guidance-only','Lite')
labels={'best-six':'Training-selected overall plan','combined-six':'Training-selected LEDs + barriers','combined-no-led':'Same combined plan, LEDs off','combined-no-barrier':'Same combined plan, barriers removed','matched-guidance-only':'Same posts and messages, both devices off','six-original-posts-guidance':'Existing posts, no devices'}
public=[]
for r in rows:public.append({k:r[k] for k in ['id','model','cfg','stats']}|{'label':labels[r['id']],'times':[{k:q.get(k) for k in ['seed','tEvac','tSafe','tSafeAll']} for q in r['runs']]})
conclusion=f"Exactly six managers: the preselected combined plan gives {f(a['stats']['mean'])} s in A, {f(combined['stats']['mean'])} s in A-Lite and {f(b['stats']['mean'])} s in B (40 independent audiences each). The mean 180-second target is not demonstrated."
Path('public/results/placement-study.json').write_text(json.dumps({'conclusion':conclusion,'status':'complete','rows':public},separators=(',',':'))+'\n')
with (R/'comparisons.csv').open('w') as out:
 w=csv.writer(out,lineterminator='\n');w.writerow(['phase','configuration','model','replications','mean_seconds','ci_low','ci_high','failures','fraction_le180','peak_density','mean_excess_density_exposure'])
 for phase,data in [('screen',screen),('shortlist',short),('confirmation',conf),('blocked',blocked),('visibility',vis)]:
  for r in data['results']:
   s=r['stats'];w.writerow([phase,r['id'],r['model'],s['n'],s['mean'],s['ciLow'],s['ciHigh'],s['failures'],s['p180']['p'],s['peakDensityMax'],s['exposureMean']])
subprocess.run(['python3','scripts/placement-figures.py'],check=True)
parts=['<!-- SIX_MANAGER_START -->','## Current scope: six managers and the original problem constraints',
'''This update addresses **Question 2** (full-house concert emergency, including an initially unknown blocked exit) and **Question 4** (removable corridor barriers and directional LED strips). The original seven-page *Bail(ey)ing Out* PDF was reread, including the evacuation plans and seating maps. The brief requires at least six managers; this comparison uses **exactly six**, as requested. Earlier 10/18-manager results remain historical resource sensitivities.

'''+table(['Constraint','Source page','Treatment'],[
['1,329 occupants, including up to three wheelchair users','2–3','All 1,329 retained, including three wheelchair users; not 1,329 plus three.'],
['Declaration to last person outside','1–2','Response time included; no 180 s censoring; building boundary and street safety reported separately.'],
['At least six staff at concerts','2','Exactly six actual posts; no staff removed by the device interventions.'],
['Temporary corridor barriers; directional floor/wall LEDs','2','Original corridor slots and finite floor-strip segments; no physical rate or width bonus.'],
['Exit obstruction and execution error','2','Matched discovery-mode blocked-door tests; visibility and notice sensitivities.'],
['No elevator; preserve building layout','3–7','Original graph and prohibited links unchanged; all candidate rows and wheelchair seats retain an egress path.'],
['One-page executive summary, explicit questions addressed','2–3','Summary addressed to Timothy Ryan precedes this report; Questions 2 and 4 selected.']]),
'''The user's target is an average below 180 s. The brief's wording is stricter: an evacuation must finish under 180 s. The report therefore shows both the mean last-person time and the count at or below 180. Graph connectivity does not establish installation feasibility, body-level pressure, smoke tenability or empirical accuracy. The full audit is `CONSTRAINTS.md`.

## Why your Model A run can differ from 230 seconds

The historical refined A result is **231.2475 s**, averaged over 40 specified audiences. It uses six existing managers, W1/E1 hard corridor panels, pre-announcement, abstract LEDs, adaptive managers and conservative service integration. The default concert baseline is **268.645 s** on the same audiences. The configuration's stored seed 1 is not the batch's first generated seed.

The archived refined A audience with seed **2132682877** leaves the building at **235.1 s**, the last ambulatory person reaches street level at **266.0 s**, and all-person street safety including scheduled wheelchair assistance is **282.7 s**. Individual clearance times in that 40-run batch span **212.9–260.1 s**. The interface's former prominent clock included outside travel and assistance; it was not the study's clearance metric. The live view now displays building clearance separately. The study tab loads exact configurations, replays a known audience, and reproduces the complete archived seed list.

A fresh current-code audit reproduced **all 1,000 runs** in the original A/B and later A-Lite main confirmation archives, including the known incomplete corrected-A case. Numerical run fields match; measured CPU runtime is excluded. Real browser checks independently matched the live A/B results and all 40 refined A worker results. Multiple local checkouts were serving different code on ports 5173/5174; this worktree serves port 5180. A shared Vite dependency cache also caused duplicate-React errors; the cache is now local to this checkout.

The generic Monte Carlo summary previously could show a completion-conditioned mean when another audience failed. It now reports no finite full-house mean for an incomplete batch, preserving failures in the success fraction. This display correction does not change trajectories. Reproduction verifies implementation consistency; it cannot establish agreement with a real Bailey evacuation without calibration data.

## Placement experiment and resource budget

Three six-manager layouts (existing, seat coverage, decision points), four LED choices (none, early approach, decision areas, corridor/exit approach) and seven barrier choices give **84 configurations**, each tested on four common training audiences. Barrier choices are none; hard W0/E0, W1/E1, W2/E2; W1/E1 ropes; and asymmetric hard W0/E2 or W2/E0. Thus symmetry is tested, not presumed.

The same expanded seat-block instructions and pre-announcement are used throughout the screen. Staff have acoustic reach and individual message hearing; congestion redirection is initially held static, while closure handling remains enabled. Four additional zone-control variants enter the longer shortlist. Physical probabilities remain 0.9 notice and 0.7 acceptance for LEDs, 0.8 base staff acceptance, with inherited imperfect hearing. Ropes add 15 perceived seconds, a sensitivity assumption rather than an observed Bailey deterrent.

Each LED layout uses **twelve 2 m floor strips, 24 m total**, clipped to existing links. The message is public and fixed; no strip reads a person's original seat. Range is 12 m, same-floor only, with walls, columns and hard panels occluding. One notice/acceptance opportunity uses the original random draws. Body occlusion, height, luminance and optical smoke effects are not calibrated. The strips are localized cues, not an uninterrupted illuminated route. Floor strips are visible from either side; arrow direction is distinct from the facing cone of a wall sign. Model Guide equation 25 specifies the finite-strip visibility calculation.

Bernardini et al. [R20] support investigating low-level directional cues and message comprehension, using isolated-person VR evidence. Galea et al. [R8] support message consistency. Neither establishes Bailey's notice/acceptance values. Barrier experiments [R11–R12,R17] show configuration-dependent benefits and harm; no published percentage is pasted onto capacity.

![All three equal-length LED layouts and all six candidate corridor barrier slots; arrows show public exit directions.](figures/placement-layouts.svg)
''']
parts.append('## Training selection, fixed before independent confirmation\n\n'+f"The shortlist contains **{len(short['results'])} candidates**, each evaluated on 12 new training audiences (base seed 61007), after screening with base seed 61006. Selection was frozen before viewing the 40-audience confirmation set (61106). The lowest training mean selected `{sel['best']}` overall; the best candidate containing both devices selected `{sel['combined']}`. These are two prespecified roles, not a choice of the best holdout result.\n\n")
rank=sorted(short['results'],key=lambda r:r['stats']['mean'] or 1e9)[:8]
parts.append(table(['Training configuration','Mean s [95% CI]','Failures'],[[r['id'],f"{f(r['stats']['mean'])} [{f(r['stats']['ciLow'])}, {f(r['stats']['ciHigh'])}]",r['stats']['failures']] for r in rank]))
parts.append('## Independent six-manager comparison\n\n'+conclusion+'\n\n'+table(['Configuration / model','Mean s [95% CI]','≤180','Unresolved'],[[labels[r['id']]+' / '+r['model'],f"{f(r['stats']['mean'])} [{f(r['stats']['ciLow'])}, {f(r['stats']['ciHigh'])}]",f"{round(r['stats']['n']*r['stats']['p180']['p'])}/{r['stats']['n']}",f"{r['stats']['failures']}/{r['stats']['n']}"] for r in rows]))
parts.append('Negative paired differences mean faster; confidence intervals describe the paired audience sample. The intervention comparison keeps posts, instructions and pre-announcement fixed.\n\n'+table(['A-Lite paired comparison','Difference s [95% CI]'],[
['Combined minus neither device',paired(combined,base)],['Add LEDs to same barrier plan',paired(combined,get('combined-no-led','Lite'))],['Add ropes to same LED plan',paired(combined,get('combined-no-barrier','Lite'))]]))
parts.append('The combined policy is retained as the prespecified device comparison even if the overall training winner performs differently on confirmation. A small LED difference with an interval containing zero is not evidence of a reliable improvement. Simpler device layouts can be preferable when the effect is uncertain. Search does not prove a global optimum.\n\n'+table(['Combined plan / model','Max local density, persons/m²','Mean exposure, persons·s/m²'],[[r['model'],f(r['stats']['peakDensityMax']),f(r['stats']['exposureMean'])] for r in [a,combined,b]])+'\nExposure integrates density above 2 persons/m² per person, then averages over people and runs. This is an analytical comparison, not a safety threshold. Local A windows, Lite whole-link averages and B edge averages differ in resolution; their peak values are not interchangeable.\n')
parts.append('## Where the selected devices and six managers are\n\nThe combined plan uses **'+cfg['crowdManagers']['placement']+'** posts, **'+combined['led']+'** LED placement, and **'+combined['barrier']+'** barriers. The frozen configuration contains every polyline point, arrow message, staff setting and seat-block instruction.\n\n![Selected combined plan: six managers, physical directional strips and corridor barriers on both floors.](figures/placement-selected.svg)\n')
parts.append(table(['Strip / existing link','Floor','Centre (x, y), m','Public destination'],[[s['id']+' / '+s['strip']['linkId'],s['floor'],f"({s['x']:.2f}, {s['y']:.2f})",s['exit']] for s in cfg['led']['spatial']['signs']]))
parts.append('Each listed strip is 2 m long along its existing link. Coordinates use east-positive x and south-positive y; they are reconstruction coordinates, not surveyed installation dimensions. Full ordered endpoints are retained in the JSON and drawn as arrows.\n\n')
positions={'existing':[(-12.8,-4.8,1),(12.8,-4.8,1),(-4.9,12.4,1),(4.9,12.4,1),(-18.4,2.85,2),(18.4,2.85,2)],'coverage':[(-5.1,-3.2,1),(5.1,-3.2,1),(-4.9,12.4,1),(4.9,12.4,1),(-18.4,2.85,2),(18.4,2.85,2)],'decision':[(0,-7,1),(0,12,1),(-16.5,7.5,1),(16.5,7.5,1),(-17.6,3.6,2),(17.6,3.6,2)]}
parts.append(table(['Manager','Existing: (x,y,floor)','Coverage: (x,y,floor)','Decision: (x,y,floor)'],[['CM'+str(i+1),*[str(positions[p][i]) for p in positions]] for i in range(6)]))
geo=json.load(open('src/data/geometry/bailey-hall.json'));slots={'W0':'CO_3','W1':'CO_7','W2':'CO_10','E2':'CO_17','E1':'CO_20','E0':'CO_24'}
parts.append(table(['Slot / link','Centre (x,y), m','Corridor width, m'],[[s+' / '+id,str(tuple(round((l['pts'][0][k]+l['pts'][-1][k])/2,3) for k in [0,1])),l['width']] for s,id in slots.items() for l in geo['links'] if l['id']==id]))
parts.append('The maps number staff CM1–CM6 for comparison; implementation IDs are CM1–CM6 for existing, CV1–CV6 for coverage and DP1–DP6 for decision posts. Panel and rope positions are the same slot midpoints; panels close the slot and obscure sight, ropes remain crossable. All six managers remain available. Staff footprint and their own evacuation remain absent from the inherited audience model.\n')
parts.append('## Blocked exit and visibility robustness\n\nTwelve matched audiences (base 61206) compare open conditions with **F3 blocked from the start**, initially discovered locally. F3 is one exterior foyer door; no door is removed from the intervention geometry. Neither the static strips nor people receive perfect initial closure information.\n\n'+table(['Policy / model','Open mean s','F3 blocked mean s','Paired change s [95% CI]'],[[id+' / '+m,f(o['stats']['mean']),f(c['stats']['mean']),paired(c,o)] for id in ['best-six','combined-six'] for m in ['A','B','Lite'] for o in blocked['results'] if o['id']==id+'-open' and o['model']==m for c in blocked['results'] if c['id']==id+'-blocked-F3' and c['model']==m]))
parts.append('The combined-policy blockage result is model-dependent: F3 closure slows A but speeds Lite in this sample. Mean foyer use in Lite falls from 650.6 to 605.6 people, redistributing demand toward portico and stage routes. This is a route-choice/queue interaction, not increased physical capacity. It is not a recommendation to close an exit, and the disagreement with A limits transfer to the real building. An additional final-state audit checks zero passages through F3 and full completion on every combined-plan blocked replicate.\n')
